INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", "2015/12/17 15:00:00", 0, 1, 106001, 0, 7001, 7, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", "2015/12/17 15:00:00", 0, 1, 105901, 0, 7002, 7, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", "2015/12/17 15:00:00", 0, 1, 105801, 0, 7003, 7, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", "2015/12/17 15:00:00", 0, 1, 105801, 0, 10001, 10, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", "2015/12/17 15:00:00", 0, 1, 106001, 0, 10002, 10, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", "2015/12/17 15:00:00", 0, 1, 105901, 0, 10003, 10, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", "2015/12/17 15:00:00", 2104010, 2, 106401, 0, 10004, 10, "シェフィ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", "2015/12/17 15:00:00", 0, 1, 105801, 0, 12001, 12, "ペコリーヌ", -416.5, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", "2015/12/17 15:00:00", 0, 1, 106001, 0, 13001, 13, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", "2015/12/17 15:00:00", 0, 1, 105901, 0, 13002, 13, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", "2015/12/17 15:00:00", 2104010, 2, 106401, 0, 13003, 13, "シェフィ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", "2015/12/17 15:00:00", 0, 1, 105801, 0, 13004, 13, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", "2015/12/17 15:00:00", 0, 1, 105901, 0, 14001, 14, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", "2015/12/17 15:00:00", 2104010, 2, 106401, 0, 14002, 14, "シェフィ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", "2015/12/17 15:00:00", 0, 1, 105801, 0, 14003, 14, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", "2015/12/17 15:00:00", 0, 1, 106001, 0, 14004, 14, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", "2015/12/17 15:00:00", 0, 1, 105901, 0, 15001, 15, "コッコロ", -470, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", "2015/12/17 15:00:00", 2104010, 2, 106401, 0, 16001, 16, "シェフィ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", "2015/12/17 15:00:00", 0, 1, 105801, 0, 16002, 16, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", "2015/12/17 15:00:00", 0, 1, 106001, 0, 16003, 16, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", "2015/12/17 15:00:00", 0, 1, 105901, 0, 16004, 16, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", "2015/12/17 15:00:00", 0, 1, 105901, 0, 17002, 17, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", "2015/12/17 15:00:00", 0, 1, 106001, 0, 17004, 25, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", "2015/12/17 15:00:00", 0, 1, 105901, 0, 17005, 25, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", "2015/12/17 15:00:00", 2104010, 2, 106401, 0, 17006, 25, "シェフィ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", "2015/12/17 15:00:00", 0, 1, 105801, 0, 17007, 25, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", "2015/12/17 15:00:00", 0, 1, 190801, 0, 18001, 18, "カリン", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 2, 0, 0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", "2015/12/17 15:00:00", 0, 1, 190801, 0, 18002, 18, "カリン", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 3, 0, 0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", "2015/12/17 15:00:00", 0, 1, 190801, 0, 19001, 19, "カリン", -470, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 4, 0, 0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", "2015/12/17 15:00:00", 0, 1, 190801, 0, 19002, 19, "カリン", -470, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 5, 0, 0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", "2015/12/17 15:00:00", 0, 1, 190801, 0, 20001, 20, "カリン", -470, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 6, 0, 0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", "2015/12/17 15:00:00", 0, 1, 190801, 0, 20002, 20, "カリン", -470, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", "2015/12/17 15:00:00", 0, 1, 106001, 0, 21001, 21, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", "2015/12/17 15:00:00", 0, 1, 105901, 0, 21002, 21, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", "2015/12/17 15:00:00", 2104010, 2, 106401, 0, 21003, 21, "シェフィ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", "2015/12/17 15:00:00", 0, 1, 105801, 0, 21004, 21, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", "2015/12/17 15:00:00", 0, 1, 190801, 0, 22001, 22, "カリン", -430, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 2, 0, 0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", "2015/12/17 15:00:00", 0, 1, 190801, 0, 22002, 22, "カリン", -430, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 3, 0, 0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", "2015/12/17 15:00:00", 0, 1, 190801, 0, 23001, 23, "カリン", -430, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 4, 0, 0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", "2015/12/17 15:00:00", 0, 1, 190801, 0, 23002, 23, "カリン", -430, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 10011, 8, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", "2019/01/31 12:00:00", 0, 1, 109001, 4.08, 24001, 24, "エリコ（バレンタイン）", -385, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 2, 10011, 8, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", "2019/01/31 12:00:00", 0, 1, 109001, 5, 24002, 24, "エリコ（バレンタイン）", -385, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 3, 10011, 8, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", "2019/01/31 12:00:00", 0, 1, 109001, 10.11, 24003, 24, "エリコ（バレンタイン）", -385, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 4, 10011, 8, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", "2019/01/31 12:00:00", 0, 1, 109001, 4, 24004, 24, "エリコ（バレンタイン）", -385, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 5, 10011, 8, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", "2019/01/31 12:00:00", 0, 1, 109001, 6, 24005, 24, "エリコ（バレンタイン）", -385, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 6, 10011, 0, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", "2019/01/31 12:00:00", 0, 1, 109002, 0, 24006, 24, "エリコ（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 7, 10011, 0, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", "2019/01/31 12:00:00", 0, 1, 109002, 0, 24007, 24, "エリコ（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 8, 10011, 0, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", "2019/01/31 12:00:00", 0, 1, 109002, 0, 24008, 24, "エリコ（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 9, 10011, 0, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", "2019/01/31 12:00:00", 0, 1, 109002, 0, 24009, 24, "エリコ（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 10, 10011, 0, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", "2019/01/31 12:00:00", 0, 1, 109002, 0, 24010, 24, "エリコ（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 10011, 8, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", "2019/01/31 12:00:00", 0, 1, 109101, 2.12, 24011, 24, "シズル（バレンタイン）", -385, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 2, 10011, 8, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", "2019/01/31 12:00:00", 0, 5, 109101, 4.19, 24012, 24, "シズル（バレンタイン）", -385, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 3, 10011, 8, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", "2019/01/31 12:00:00", 0, 2, 109101, 2.3, 24013, 24, "シズル（バレンタイン）", -385, 4);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 4, 10011, 0, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", "2019/01/31 12:00:00", 0, 1, 109102, 0, 24014, 24, "シズル（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 5, 10011, 8, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", "2019/01/31 12:00:00", 0, 5, 109101, 5.23, 24015, 24, "シズル（バレンタイン）", -385, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 6, 10011, 0, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", "2019/01/31 12:00:00", 0, 1, 109102, 0, 24016, 24, "シズル（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 7, 10011, 8, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", "2019/01/31 12:00:00", 0, 1, 109101, 5.01, 24017, 24, "シズル（バレンタイン）", -385, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 8, 10011, 0, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", "2019/01/31 12:00:00", 0, 1, 109102, 0, 24018, 24, "シズル（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 9, 10011, 0, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", "2019/01/31 12:00:00", 0, 1, 109102, 0, 24019, 24, "シズル（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 10, 10011, 0, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", "2019/01/31 12:00:00", 0, 1, 109102, 0, 24020, 24, "シズル（バレンタイン）", 0, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", "2015/12/17 15:00:00", 2104010, 2, 106401, 0, 26001, 26, "シェフィ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", "2015/12/17 15:00:00", 0, 1, 105801, 0, 26002, 26, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", "2015/12/17 15:00:00", 0, 1, 106001, 0, 26003, 26, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", "2015/12/17 15:00:00", 0, 1, 105901, 0, 26004, 26, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", "2015/12/17 15:00:00", 2104010, 2, 106401, 0, 27001, 27, "シェフィ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", "2015/12/17 15:00:00", 0, 1, 105801, 0, 27002, 27, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", "2015/12/17 15:00:00", 0, 1, 106001, 0, 27003, 27, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", "2015/12/17 15:00:00", 0, 1, 105901, 0, 27004, 27, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", "2019/09/24 15:00:00", 0, 1, 190801, 0, 28001, 28, "カリン", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 2, 0, 0, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", "2019/09/24 15:00:00", 0, 1, 190801, 0, 28002, 28, "カリン", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 3, 0, 0, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", "2019/09/24 15:00:00", 0, 1, 190801, 0, 29001, 29, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 4, 0, 0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", "2019/09/24 15:00:00", 0, 1, 190801, 0, 29002, 29, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 5, 0, 0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", "2019/09/24 15:00:00", 0, 1, 190801, 0, 30001, 30, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 6, 0, 0, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", "2019/09/24 15:00:00", 0, 1, 190801, 0, 30002, 30, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 7, 0, 0, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", "2019/10/31 12:00:00", 0, 1, 190801, 0, 31001, 31, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 8, 0, 0, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", "2019/10/31 12:00:00", 0, 1, 190801, 0, 31002, 31, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2020/01/04 4:59:59", 1, 0, 0, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", "2019/12/20 5:00:00", 0, 1, 190801, 0, 32001, 32, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2020/01/04 4:59:59", 2, 0, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "2019/12/20 5:00:00", 0, 1, 190801, 0, 32002, 32, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2020/01/04 4:59:59", 3, 0, 0, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", "2019/12/20 5:00:00", 0, 1, 190801, 0, 33001, 33, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2020/01/04 4:59:59", 4, 0, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "2019/12/20 5:00:00", 0, 1, 190801, 0, 33002, 33, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2020/01/10 11:59:59", 5, 0, 0, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", "2020/01/04 5:00:00", 0, 1, 190801, 0, 34001, 34, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2020/01/10 11:59:59", 6, 0, 0, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", "2020/01/04 5:00:00", 0, 1, 190801, 0, 34002, 34, "カリン", -409, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", "2015/12/17 15:00:00", 0, 1, 105801, 5.3, 38001, 38, "ペコリーヌ", -458, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 2, 0, 0, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", "2015/12/17 15:00:00", 0, 1, 105801, 6.5, 38002, 38, "ペコリーヌ", -458, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2020/04/08 23:59:59", 0, 0, 9999, "", "2020/04/01", 0, 3, 105801, 0, 39005, 39, "ペコリーヌ", 9999, 3);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 2, 0, 0, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", "2015/12/17 15:00:00", 0, 1, 190801, 0, 40001, 40, "カリン", -430, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", "2015/12/17 15:00:00", 2104010, 1, 106401, 0, 41001, 41, "シェフィ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", "2015/12/17 15:00:00", 0, 1, 105801, 0, 41002, 41, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", "2015/12/17 15:00:00", 0, 1, 106001, 0, 41003, 41, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", "2015/12/17 15:00:00", 0, 1, 105901, 0, 41004, 41, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", "2015/12/17 15:00:00", 0, 1, 105901, 0, 42001, 42, "コッコロ", -416.5, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", "2015/12/17 15:00:00", 2104010, 1, 106401, 0, 42002, 42, "シェフィ", -416.5, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", "2015/12/17 15:00:00", 0, 1, 105801, 0, 42003, 42, "ペコリーヌ", -416.5, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", "2015/12/17 15:00:00", 0, 1, 106001, 0, 42004, 42, "キャル", -416.5, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", "2015/12/17 15:00:00", 0, 1, 105801, 0, 43001, 43, "ペコリーヌ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", "2015/12/17 15:00:00", 0, 1, 105901, 0, 43002, 43, "コッコロ", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", "2015/12/17 15:00:00", 0, 1, 106001, 0, 43003, 43, "キャル", -363, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", "2015/12/17 15:00:00", 0, 1, 123001, 0, 43004, 44, "アメス", -416.5, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 2, 0, 0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", "2015/12/17 15:00:00", 0, 1, 123001, 0, 43005, 44, "アメス", -416.5, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 3, 0, 0, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", "2015/12/17 15:00:00", 0, 1, 123001, 5.79, 43006, 45, "アメス", -416.5, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", "2015/12/17 15:00:00", 0, 1, 123001, 0, 46001, 46, "アメス", -371.5, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", "2015/12/17 15:00:00", 0, 2, 104901, 0, 47001, 47, "シズル", -416.5, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 1, 0, 0, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", "2015/12/17 15:00:00", 0, 1, 101101, 9.32, 47002, 47, "リノ", -416.5, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 0, 0, 0, "", "2015/12/17 15:00:00", 0, 2, 104901, 0, 48001, 48, "シズル", -470, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 0, 0, 0, "", "2015/12/17 15:00:00", 0, 2, 101101, 0, 48002, 48, "リノ", -470, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 0, 0, -15, "", "2015/12/17 15:00:00", 0, 1, 134901, 0, 49001, 49, "カノン", -290, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("2030/12/17 14:59:59", 0, 0, -15, "", "2015/12/17 15:00:00", 0, 1, 190801, 0, 50001, 50, "カリン", -450, 2);
